"""Authored individual rescue dialogue; run after generate_campaign.py."""
from pathlib import Path
import json
R=Path(__file__).resolve().parents[1]
c=json.loads((R/'data/campaign.json').read_text())
LINES=[
['Лада: Не хватайте её за повод. Она вернулась сама — значит, привела вас.','Тим: Я слышал, как она звала за деревьями. Теперь можно ответить.','Сава: Дома у меня осталась закваска. Глупо думать о хлебе сейчас? Нет? Тогда пойдём.'],
['Орина: Птицу оставлю здесь. Пусть следующему путнику будет видно, что дверь открыта.','Бран: Через щель не идите. Камень сдвинулся; я покажу широкий проход.','Мила: Подождите миг. Я должна привыкнуть, что могу выбрать, куда поставить ногу.'],
['Энна: Я считала дни по нитям на рукаве. Последнюю распущу уже дома.','Радек: Ступень слева шатается. Держитесь за меня, пока спускаемся.','Ивар: Лада, Тим, Сава… Я помню всех. Запишем, чтобы больше не терялись.'],
['Верна: Не смотрите только вперёд. Зарубка с обратной стороны ствола тоже ведёт домой.','Олек: Я донесу сумку. Только разрешите не держаться больше за решётку.','Нела: В глине остались наши следы. Давайте сегодня оставим их за пределами клетки.'],
['Дарна: Ткань держалась на последнем узле. Хорошо, что не отпустила.','Егор: На воду не ступайте. Тёмная полоса глубже, чем кажется.','Рута: Я сошью новую ленту. Эту выбрасывать не стану.'],
['Федор: Молодые деревья не трогайте. Круг обгорел давно; лес уже возвращается.','Ася: Я помню, где растут ягоды. Сейчас мне нужна только дорога к воротам.','Марен: Замок сделан умело. Жаль, что умение пошло на такую работу.'],
['Лина: Сначала проверим настил. Вода никуда не торопится; и нам не надо.','Торен: Я подтянул поручень. Держитесь здесь, когда пойдём вниз.','Сима: У меня дрожат руки. Я помогу другим, когда мы окажемся на сухом берегу.'],
['Ярина: Можно больше не делить песню на строки? Я хочу допеть её целиком.','Век: Я пометил выходы травой. По одному из них мы уже не вернёмся.','Дина: Эти пучки оставим. Другому человеку тоже понадобится увидеть путь.'],
['Мирен: Не смейтесь над картой. Рисовал её углём на колене.','Бела: За плитой хороший спуск. Я запомнила его ещё до того, как нас привели.','Стас: Когда вернусь к кузнице, первым делом сделаю петлю для двери, которая никого не держит.'],
['Грета: Плита звенит под ногой. Здесь не стоим; идём вдоль тёмного шва.','Леван: Я всё время составлял список потерянного груза. Сегодня вычеркну из него нас.','Ника: Если дома осталось хоть немного муки, я испеку хлеб всем, кто вернулся.'],
['Марта: Я знаю этот берег. Раньше люди платили мне за переправу. Сегодня достаточно идти рядом.','Рен: Не срывайте белые цветы у воды. Они покажут, где кончается сухая ступень.','Алва: Мне казалось, дома обо мне уже говорят в прошедшем времени. Пойдём скорее.'],
['Тала: Я расскажу о Костяной чаше дома. Сначала пусть все трое дойдут до ворот.','Мирко: Эти кости слишком велики для здешних стражей. Не преследуйте звук за деревьями.','Эда: Последняя клетка… Скажите это ещё раз. Я хочу запомнить, как звучат эти слова.']]
entries=[]
for site,lines in zip(c['sites'],LINES):
 for person,line in zip(site['captives'],lines):
  name,body=line.split(': ',1)
  assert name==person['name']
  entries.append({'id':person['id']+'_released','speakerId':person['id'],'speaker':name,'role':person['role'],'when':'site step >=4; play once visually, always rereadable','text':body})
 entries.append({'id':site['id']+'_testimony','speakerId':site['captives'][0]['id'],'speaker':site['captives'][0]['name'],'when':'site step5','text':site['testimony']})
entries += [
 {'id':'horse_intro','speakerId':'narrator','speaker':'Наблюдение','when':'prologue','paragraphs':c['prologue']['intro']},
 {'id':'horse_return','speakerId':'lf_captive_01_a','speaker':'Лада','when':'lf_site_01 step5','text':'Её зовут Искра. Она боится сильного ветра, но нашла вас через весь лес. Берегите её, пока идёте за остальными.'},
 {'id':'boss_warning','speakerId':'lf_captive_12_a','speaker':'Тала','when':'all 12 sites step5','text':'Все люди вернулись. За рощей старых костей больше нет клеток. Там живёт Пращур. Мы слышали, как после его шагов осыпается камень. Если решите идти, оставьте нас здесь — дома.'},
 {'id':'boss_enter','speakerId':'narrator','speaker':'Костяная чаша','when':'boss_active','text':'Деревья замолкают. Над старой костью поднимается голова, слишком большая для привычного леса. Пращур медленно разворачивается к отряду.'},
 {'id':'boss_end','speakerId':'narrator','speaker':'Тридцать шесть дорог домой','when':'completed','text':c['boss']['endingText']}
]
d={'schemaVersion':1,'campaignId':'forest_rescue_v1','locale':'ru-RU','plainTextOnly':True,'voiceActingDelivered':False,'entries':entries,'playbackPolicy':'Dialogue never blocks combat orders or server mutations; repeat reading has no rewards; no fabricated portraits or spoken audio.'}
(R/'data/dialogue.ru.json').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
parts=['# Сценарии двенадцати спасений\n','Источник: `data/campaign.json`, `data/dialogue.ru.json`. Реплики написаны для текста; озвучка не заявлена. Имя коня — Искра, гнедая кобыла. Каждое место: исследование → артефакт → страж → клетка → сопровождение.\n']
parts += ['## До начала: ратуша III\n','На уровнях I–II внешний лес закрыт красивым анимированным туманом. Текст: «Достигните 3-го уровня ратуши, чтобы открыть приключение». После завершения уровняIII: уведомление → вход в тумане → Искра без всадника → объяснение спасения людей. Точная12-секундная постановка, пропуск и восстановление: data/unlock-intro.json и docs/HALL3_UNLOCK_AND_INTRO_RU.md. Награда за просмотр отсутствует; prologue оплачивает только настоящее прибытие.\n']
for s in c['sites']:
 parts += [f'## {s["number"]:02}. {s["name"]}\n',f'ID: `{s["id"]}`. Круг {s["act"]}. Страж: {s["guardian"]["species"]}, уровень {s["guardian"]["level"]}. Артефакт: **{s["artifact"]["name"]}** (`{s["artifact"]["id"]}`).\n', 'Люди: '+', '.join(p['name']+' — '+p['role'] for p in s['captives'])+'.\n']
 for t in s['tasks']:
  parts += [f'**{t["order"]}. {t["title"]}.** {t["objective"]}\n']
 parts += ['**После открытия.** '+s['tasks'][3]['resultText']+'\n','**Свидетельство дома.** «'+s['testimony']+'»\n','**След в окружении.** '+s['postState']+'\n']
parts += ['## Финал\n',next(e['text'] for e in entries if e['id']=='boss_warning')+'\n',next(e['text'] for e in entries if e['id']=='boss_enter')+'\n',next(e['text'] for e in entries if e['id']=='boss_end')+'\n']
(R/'docs/NARRATIVE_RU.md').write_text('\n'.join(parts))
print(f'{len(entries)} dialogue entries, 36 distinct speakers, 12 site scenarios')
